create table public.paper_reports(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id)on delete cascade,paper_id text not null references public.papers(id)on delete cascade,reason text not null check(length(reason)between 5 and 1000),status text not null default 'open'check(status in('open','reviewed')),review_reason text not null default ''check(review_reason=''or length(review_reason)between 5 and 1000),created_at timestamptz not null default now());
create unique index paper_report_open_unique on public.paper_reports(user_id,paper_id)where status='open';
alter table public.paper_reports enable row level security;
revoke all on public.paper_reports from public,anon,authenticated;grant select on public.paper_reports to authenticated;grant all on public.paper_reports to service_role;
create policy paper_reports_read on public.paper_reports for select to authenticated using(user_id=auth.uid()or private.has_role('metadata_editor')or private.has_role('moderator')or private.has_role('admin'));
drop policy audit_read on public.audit;
create policy audit_read on public.audit for select to authenticated using(private.has_role('admin')or(private.has_role('reviewer')and action like 'membership_%')or(private.has_role('moderator')and(action like 'moderate%'or action='paper_report_review'))or(private.has_role('metadata_editor')and action='paper_report_review'));
create or replace function public.trust_action(action_type text,payload jsonb,request_id uuid)returns void language plpgsql security definer set search_path=''as $$declare uid uuid:=auth.uid();pid uuid:=(payload->>'post_id')::uuid;cid uuid:=(payload->>'comment_id')::uuid;prid uuid:=(payload->>'project_id')::uuid;begin
 if action_type='appeal_content'then if uid is null or not exists(select 1 from public.posts where id=pid and author_id=uid and state='removed')or not exists(select 1 from public.audit where target_id=pid::text and action='moderate')then raise insufficient_privilege;end if;perform private.rate_limit('appeal',3);insert into public.content_appeals(user_id,post_id,reason)values(uid,pid,payload->>'reason')on conflict(user_id,post_id)do nothing;return;end if;
 if uid is null or not private.member()then raise insufficient_privilege;end if;if pg_column_size(payload)>12000 then raise exception 'Payload too large';end if;
 insert into private.action_receipts(user_id,request_id,action)values(uid,request_id,'trust:'||action_type)on conflict do nothing;if not found then return;end if;perform private.rate_limit('all',60);
 if action_type='subscribe'then if not private.post_read(pid)then raise insufficient_privilege;end if;delete from public.subscriptions where user_id=uid and post_id=pid;if not found then insert into public.subscriptions values(uid,pid);end if;
 elsif action_type='paper_report'then perform private.rate_limit('paper_report',3);insert into public.paper_reports(user_id,paper_id,reason)values(uid,payload->>'paper_id',payload->>'reason')on conflict(user_id,paper_id)where status='open'do nothing;
 elsif action_type='review_paper_report'then if not(private.has_role('metadata_editor')or private.has_role('moderator')or private.has_role('admin'))then raise insufficient_privilege;end if;update public.paper_reports set status='reviewed',review_reason=payload->>'reason'where id=(payload->>'report_id')::uuid and status='open';if not found then raise exception 'Report unavailable';end if;insert into public.audit(actor_id,action,target_id,reason)values(uid,'paper_report_review',payload->>'report_id',payload->>'reason');perform private.notify(user_id,'paper_report:'||id::text,'moderation','Your scholarly metadata report was reviewed','/notifications')from public.paper_reports where id=(payload->>'report_id')::uuid;
 elsif action_type='unsave_paper'then delete from public.paper_saves where user_id=uid and paper_id=payload->>'paper_id';
 elsif action_type='resolve_content_appeal'then if not(private.has_role('admin')or private.has_role('moderator'))then raise insufficient_privilege;end if;update public.content_appeals set status=case when(payload->>'accept')::boolean then'accepted'else'rejected'end,review_reason=payload->>'reason'where id=(payload->>'appeal_id')::uuid and status='pending'and exists(select 1 from public.posts p where p.id=post_id and p.visibility<>'private'and(p.project_id is null or private.project_read(p.project_id)));if not found then raise insufficient_privilege;end if;if(payload->>'accept')::boolean then update public.posts set state='published',updated_at=now()where id=(select post_id from public.content_appeals where id=(payload->>'appeal_id')::uuid);end if;insert into public.audit(actor_id,action,target_id,reason)values(uid,'moderate_appeal',payload->>'appeal_id',payload->>'reason');
 elsif action_type='edit_comment'then if not exists(select 1 from public.comments c where c.id=cid and c.author_id=uid and private.post_read(c.post_id))then raise insufficient_privilege;end if;update public.comments set body=trim(payload->>'body')where id=cid;
 elsif action_type='delete_project'then if not exists(select 1 from public.projects p where p.id=prid and p.owner_id=uid)or payload->>'confirm'<>'DELETE'then raise insufficient_privilege;end if;delete from public.projects where id=prid;
 elsif action_type='taxonomy'then if not private.has_role('admin')then raise insufficient_privilege;end if;insert into public.topics(name)values(trim(payload->>'name'))on conflict do nothing;insert into public.audit(actor_id,action,target_id,reason)values(uid,'taxonomy',payload->>'name',payload->>'reason');
 elsif action_type='point_rule'then if not private.has_role('admin')then raise insufficient_privilege;end if;update public.contribution_rules set points=(payload->>'points')::integer where kind='accepted_answer';insert into public.audit(actor_id,action,target_id,reason)values(uid,'point_rule','accepted_answer',payload->>'reason');
 else raise exception 'Unsupported trust action';end if;
end$$;
revoke all on function public.trust_action(text,jsonb,uuid)from public,anon;grant execute on function public.trust_action(text,jsonb,uuid)to authenticated;
create or replace function public.trust_metadata()returns jsonb language sql stable security invoker set search_path=''as $$select jsonb_build_object('paper_reports',(select coalesce(jsonb_agg(x),'[]')from(select *from public.paper_reports order by created_at desc limit 100)x),'taxonomy',(select coalesce(jsonb_agg(name order by name),'[]')from public.topics),'point_rules',(select coalesce(jsonb_agg(x),'[]')from public.contribution_rules x),'subscriptions',(select coalesce(jsonb_agg(x),'[]')from(select *from public.subscriptions limit 100)x),'appeals',(select coalesce(jsonb_agg(x),'[]')from(select *from public.content_appeals order by created_at limit 100)x),'own_removed',public.own_moderation_decisions(),'paper_saves',(select coalesce(jsonb_agg(x),'[]')from(select *from public.paper_saves limit 100)x),'contribution_total',(select coalesce(sum(points),0)from public.contributions where valid and user_id=auth.uid()))$$;
